from itertools import combinations
import math

def combinations_k(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def check_n(n):
    # We want to find the minimum number of monochromatic triangles (T_R + T_B)
    # for a given n, by iterating over all possible color splits (n_R, n_B).
    min_triangles = float('inf')

    # We only need to check splits where n_R <= n_B due to symmetry
    for n_R in range(n // 2 + 1):
        n_B = n - n_R
        triangles = combinations_k(n_R, 3) + combinations_k(n_B, 3)
        min_triangles = min(min_triangles, triangles)

    return min_triangles

# Test values n=3 up to n=8 as requested/needed
test_values = [3, 4, 5, 6, 7, 8]
results = {}
for n in test_values:
    results[n] = check_n(n)

print(results)
